#include <bits/stdc++.h>

using namespace std;

const int MAXN = 2345678;

double real_probs[123], probs[123];
double dp_state[MAXN];
double final_results[123];
int position_idx[123];
int popcnt[MAXN];

int main() {
    int total_nums, max_k;
    scanf("%d %d", &total_nums, &max_k);
    int count_valid = 0;
    for (int i = 0; i < total_nums; i++) {
        scanf("%lf", real_probs + i);
        if (real_probs[i] > 1e-4) {
            position_idx[count_valid] = i;
            probs[count_valid] = real_probs[i];
            count_valid++;
        }
    }
    max_k = min(max_k, count_valid);
    popcnt[0] = 0;
    for (int mask = 1; mask < (1 << count_valid); mask++) {
        popcnt[mask] = popcnt[mask & (mask - 1)] + 1;
    }
    for (int mask = 0; mask < (1 << count_valid); mask++) {
        dp_state[mask] = 0.0;
    }
    for (int i = 0; i < total_nums; i++) {
        final_results[i] = 0.0;
    }
    dp_state[0] = 1.0;
    for (int mask = 0; mask < (1 << count_valid); mask++) {
        if (popcnt[mask] == max_k) {
            for (int j = 0; j < count_valid; j++) {
                if (mask & (1 << j)) {
                    final_results[position_idx[j]] += dp_state[mask];
                }
            }
            continue;
        }
        double sum_probs = 0;
        for (int j = 0; j < count_valid; j++) {
            if (mask & (1 << j)) continue;
            sum_probs += probs[j];
        }
        double ratio = dp_state[mask] / sum_probs;
        for (int j = 0; j < count_valid; j++) {
            if (mask & (1 << j)) continue;
            dp_state[mask | (1 << j)] += probs[j] * ratio;
        }
    }
    for (int i = 0; i < total_nums; i++) {
        if (i > 0) cout << " ";
        printf("%.17f", final_results[i]);
    }
    printf("\n");
    return 0;
}
